def _front(raw: str) -> dict[str, str]:
    head = raw.split("---\n", 2)[1]
    fields: dict[str, str] = {}
    for line in head.splitlines():
        key, _, value = line.partition(": ")
        fields[key] = json.loads(value) if value.startswith('"') else value
    return fields
